<?php
function application_response($a){$a['id']=(int)$a['id'];$a['created_at']=iso_date($a['created_at']);return $a;}
function application_by_id($pdo,$id){$s=$pdo->prepare('SELECT * FROM applications WHERE id=?');$s->execute(array($id));$a=$s->fetch();if(!$a)error_response('Заявку не знайдено.',404);return application_response($a);}
function create_application($pdo){$i=json_body();require_fields($i,array('name','contact_information','message'));$pdo->prepare("INSERT INTO applications(name,contact_information,message,status) VALUES(?,?,?,'Нове')")->execute(array($i['name'],$i['contact_information'],$i['message']));json_response(application_by_id($pdo,$pdo->lastInsertId()),201);}
function list_applications($pdo){require_admin($pdo);$where=array();$v=array();if(isset($_GET['status'])){$where[]='status=?';$v[]=$_GET['status'];}if(isset($_GET['search'])){$where[]='(name LIKE ? OR contact_information LIKE ? OR message LIKE ?)';$x='%'.$_GET['search'].'%';$v=array_merge($v,array($x,$x,$x));}$s=$pdo->prepare('SELECT * FROM applications'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC');$s->execute($v);$out=array();foreach($s->fetchAll()as$a)$out[]=application_response($a);json_response($out);}
